<?php
$bookingLabels=['pending'=>'Chờ duyệt','confirmed'=>'Đã xác nhận','rejected'=>'Bị từ chối','cancelled'=>'Đã hủy','completed'=>'Hoàn thành'];
$filters=[''=>'Tất cả','unpaid'=>'Chưa thanh toán','paid'=>'Đã thanh toán','refunded'=>'Đã hoàn tiền','not_required'=>'Không cần thanh toán'];
?>
<section class="page-section"><div class="container">
<div class="section-title"><div><p class="eyebrow">VẬN HÀNH</p><h1>Thanh toán</h1><p>Khách thanh toán trực tiếp khi nhận phòng. Host hoặc Admin ghi nhận “Đã thu tiền” từ ngày nhận phòng; hoàn tiền cần ghi chú và được lưu nhật ký.</p></div><a class="btn btn-ghost text-nowrap" href="<?= e(url('/admin')) ?>">Quay lại quản trị</a></div>
<div class="stat-grid payment-totals"><div><span>Đã thu</span><strong><?= number_format((float)($totals['collected_amount']??0),0,',','.') ?>đ</strong><small><?= (int)($totals['paid_count']??0) ?> booking</small></div><div><span>Chờ thu (đã xác nhận)</span><strong><?= number_format((float)($totals['outstanding_amount']??0),0,',','.') ?>đ</strong><small><?= (int)($totals['outstanding_count']??0) ?> booking</small></div><div><span>Đã hoàn tiền</span><strong><?= number_format((float)($totals['refunded_amount']??0),0,',','.') ?>đ</strong><small><?= (int)($totals['refunded_count']??0) ?> booking</small></div></div>
<section class="surface-card mt-4"><form class="form-row align-items-end" method="get" action="<?= e(url('/admin/payments')) ?>"><div class="form-group col-md-4"><label for="payment-status">Trạng thái thanh toán</label><select class="form-control" id="payment-status" name="status"><?php foreach($filters as $value=>$label): ?><option value="<?= e($value) ?>" <?= $status===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="form-group col-md-5"><label for="payment-search">Mã booking, tên/email khách hoặc tên chỗ ở</label><input class="form-control" id="payment-search" name="q" maxlength="254" value="<?= e($query) ?>"></div><div class="form-group col-md-3"><button class="btn btn-outline-primary btn-block" type="submit">Lọc</button></div></form>
<?php if(!$payments): ?><div class="empty-state"><h3>Không có booking phù hợp</h3><p>Thử bỏ bộ lọc hoặc tìm bằng từ khóa khác.</p><?php if($status!==''||$query!==''): ?><a class="btn btn-primary" href="<?= e(url('/admin/payments')) ?>">Xóa bộ lọc</a><?php endif; ?></div><?php else: ?>
<p class="text-muted small">Hiển thị <?= count($payments) ?> booking mới nhất<?= count($payments)>=200?' (tối đa 200; hãy lọc để thu hẹp)':'' ?>.</p>
<div class="table-responsive" tabindex="0" role="region" aria-label="Danh sách thanh toán"><table class="table payment-table"><thead><tr><th>Booking</th><th>Khách / Host</th><th>Ngày ở</th><th>Số tiền</th><th>Thanh toán</th><th>Thao tác</th></tr></thead><tbody>
<?php foreach($payments as $payment): ?><tr><td><a href="<?= e(url('/bookings/'.(int)$payment['booking_id'])) ?>">#<?= (int)$payment['booking_id'] ?></a> · <?= e($payment['title']) ?><br><span class="status status-<?= e($payment['booking_status']) ?>"><?= e($bookingLabels[$payment['booking_status']]??$payment['booking_status']) ?></span><?php if($payment['promotion_code']!==''): ?> <small class="promo-code"><?= e($payment['promotion_code']) ?></small><?php endif; ?></td>
<td><?= e($payment['guest_name']) ?><br><small><?= e($payment['guest_email']) ?></small><br><small>Host: <?= e($payment['host_name']) ?></small></td>
<td><?= e(date('d/m/Y',strtotime($payment['check_in']))) ?> → <?= e(date('d/m/Y',strtotime($payment['check_out']))) ?></td>
<td><?= number_format((float)$payment['amount_due'],0,',','.') ?>đ</td>
<td><span class="status status-<?= e($payment['payment_state']) ?>"><?= e(\App\Models\BookingExtras::paymentLabel($payment['payment_state'])) ?></span><?php if($payment['paid_at']): ?><br><small>Thu: <?= e(substr($payment['paid_at'],0,16)) ?></small><?php endif; ?><?php if($payment['refunded_at']): ?><br><small>Hoàn: <?= e(substr($payment['refunded_at'],0,16)) ?></small><?php endif; ?><?php if($payment['payment_note']): ?><br><small class="text-muted"><?= e($payment['payment_note']) ?></small><?php endif; ?></td>
<td><?php if($payment['can_mark_paid']): ?><form method="post" action="<?= e(url('/admin/payments/'.(int)$payment['booking_id'].'/paid')) ?>"><?= csrf_field() ?><button class="btn btn-sm btn-soft" data-confirm="Xác nhận đã thu <?= e(number_format((float)$payment['amount_due'],0,',','.')) ?>đ của booking #<?= (int)$payment['booking_id'] ?>?">Đã thu tiền</button></form>
<?php elseif($payment['payment_status']==='paid'): ?><form class="refund-form" method="post" action="<?= e(url('/admin/payments/'.(int)$payment['booking_id'].'/refund')) ?>"><?= csrf_field() ?><label class="sr-only" for="refund-note-<?= (int)$payment['booking_id'] ?>">Lý do hoàn tiền booking #<?= (int)$payment['booking_id'] ?></label><input class="form-control form-control-sm mb-1" id="refund-note-<?= (int)$payment['booking_id'] ?>" name="note" maxlength="500" placeholder="Lý do hoàn tiền" required><button class="btn btn-sm btn-outline-danger" data-confirm="Ghi nhận đã hoàn tiền booking #<?= (int)$payment['booking_id'] ?>? Thao tác được lưu nhật ký.">Hoàn tiền</button></form>
<?php elseif($payment['payment_state']==='unpaid' && in_array($payment['booking_status'],['confirmed','completed'],true)): ?><small class="text-muted">Thu từ ngày nhận phòng</small><?php else: ?><span class="text-muted">—</span><?php endif; ?></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?></section>
</div></section>
